// Claude's review tests for A11 (match on query, body or a header). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { hasConditions, matchConditions } from './conditions';
import { exportProject, parseProjectFile } from './exportFile';
import { findMock } from './match';
import { testCall } from './testCall';
import { newProject, type Mock, type MockMatch, type RequestFacts } from './types';

function mock(id: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    enabled: true,
    method: 'ANY',
    urlPattern: '/api/items',
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

const facts = (url: string, extra: Partial<RequestFacts> = {}): RequestFacts => ({ method: 'GET', url: `http://a.test${url}`, ...extra });

describe('hasConditions', () => {
  it('is false with no match, or only empty parts', () => {
    expect(hasConditions(mock('a'))).toBe(false);
    expect(hasConditions(mock('a', { match: {} }))).toBe(false);
    expect(hasConditions(mock('a', { match: { query: {}, headers: {}, body: '  ' } }))).toBe(false);
  });
  it('is true with any query, header or body condition', () => {
    expect(hasConditions(mock('a', { match: { query: { p: '1' } } }))).toBe(true);
    expect(hasConditions(mock('a', { match: { headers: { 'x-a': '1' } } }))).toBe(true);
    expect(hasConditions(mock('a', { match: { body: 'x' } }))).toBe(true);
  });
});

describe('matchConditions: query', () => {
  const m: MockMatch = { query: { page: '2', sort: 'name' } };
  it('needs every key with its value', () => {
    expect(matchConditions(m, facts('/api/items?page=2&sort=name&x=1'))).toBe(true);
    expect(matchConditions(m, facts('/api/items?page=2'))).toBe(false);
    expect(matchConditions(m, facts('/api/items?page=3&sort=name'))).toBe(false);
  });
  it('accepts any of repeated values', () => {
    expect(matchConditions({ query: { tag: 'b' } }, facts('/api/items?tag=a&tag=b'))).toBe(true);
  });
  it('* means present with any value, even empty', () => {
    expect(matchConditions({ query: { debug: '*' } }, facts('/api/items?debug='))).toBe(true);
    expect(matchConditions({ query: { debug: '*' } }, facts('/api/items?debug=0'))).toBe(true);
    expect(matchConditions({ query: { debug: '*' } }, facts('/api/items'))).toBe(false);
  });
  it('decodes values', () => {
    expect(matchConditions({ query: { q: 'a b' } }, facts('/api/items?q=a%20b'))).toBe(true);
  });
});

describe('matchConditions: headers', () => {
  it('compares names case-insensitively and values exactly', () => {
    const m: MockMatch = { headers: { 'X-Role': 'admin' } };
    expect(matchConditions(m, facts('/x', { headers: { 'x-role': 'admin' } }))).toBe(true);
    expect(matchConditions(m, facts('/x', { headers: { 'X-ROLE': 'admin' } }))).toBe(true);
    expect(matchConditions(m, facts('/x', { headers: { 'x-role': 'Admin' } }))).toBe(false);
    expect(matchConditions(m, facts('/x', { headers: {} }))).toBe(false);
    expect(matchConditions(m, facts('/x'))).toBe(false);
  });
  it('* means present', () => {
    expect(matchConditions({ headers: { authorization: '*' } }, facts('/x', { headers: { Authorization: 'Bearer t' } }))).toBe(true);
    expect(matchConditions({ headers: { authorization: '*' } }, facts('/x', { headers: {} }))).toBe(false);
  });
});

describe('matchConditions: body', () => {
  const post = (body: string | undefined) => facts('/api/login', { method: 'POST', body });
  it('a JSON condition is a nested subset of a JSON body', () => {
    const m: MockMatch = { body: '{"user":"anna","opts":{"remember":true}}' };
    expect(matchConditions(m, post('{"user":"anna","pw":"x","opts":{"remember":true,"lang":"vi"}}'))).toBe(true);
    expect(matchConditions(m, post('{"user":"anna","opts":{"remember":false}}'))).toBe(false);
    expect(matchConditions(m, post('{"user":"anna"}'))).toBe(false);
    expect(matchConditions(m, post('{"user":"bob","opts":{"remember":true}}'))).toBe(false);
  });
  it('values compare by type', () => {
    expect(matchConditions({ body: '{"n":1}' }, post('{"n":"1"}'))).toBe(false);
    expect(matchConditions({ body: '{"n":null}' }, post('{"n":null}'))).toBe(true);
    expect(matchConditions({ body: '{"n":null}' }, post('{}'))).toBe(false);
  });
  it('arrays must have the same length, each item a subset', () => {
    expect(matchConditions({ body: '{"ids":[1,2]}' }, post('{"ids":[1,2]}'))).toBe(true);
    expect(matchConditions({ body: '{"ids":[1,2]}' }, post('{"ids":[1,2,3]}'))).toBe(false);
    expect(matchConditions({ body: '[{"a":1}]' }, post('[{"a":1,"b":2}]'))).toBe(true);
  });
  it('otherwise the condition is a substring of the body', () => {
    expect(matchConditions({ body: 'user=anna' }, post('user=anna&pw=x'))).toBe(true);
    expect(matchConditions({ body: 'user=anna' }, post('user=bob'))).toBe(false);
    // A JSON condition against a non-JSON body falls back to substring.
    expect(matchConditions({ body: '{"a":1}' }, post('x {"a":1} y'))).toBe(true);
    expect(matchConditions({ body: 'anna' }, post(undefined))).toBe(false);
  });
  it('all three parts must hold together', () => {
    const m: MockMatch = { query: { v: '2' }, headers: { 'x-a': '1' }, body: 'hi' };
    const ok = { method: 'POST', url: 'http://a.test/x?v=2', headers: { 'x-a': '1' }, body: 'hi there' };
    expect(matchConditions(m, ok)).toBe(true);
    expect(matchConditions(m, { ...ok, url: 'http://a.test/x' })).toBe(false);
    expect(matchConditions(m, { ...ok, headers: {} })).toBe(false);
    expect(matchConditions(m, { ...ok, body: 'bye' })).toBe(false);
  });
  it('empty parts are no condition', () => {
    expect(matchConditions({ query: {}, headers: {}, body: '' }, facts('/x'))).toBe(true);
  });
});

describe('findMock with conditions', () => {
  const list = [
    mock('all'),
    mock('page2', { match: { query: { page: '2' } } }),
    mock('admin', { match: { headers: { 'x-role': 'admin' } } }),
    mock('off', { enabled: false, match: { query: { page: '3' } } }),
  ];
  it('tries mocks with conditions first, in list order, then the others', () => {
    expect(findMock(list, facts('/api/items'))?.id).toBe('all');
    expect(findMock(list, facts('/api/items?page=2'))?.id).toBe('page2');
    expect(findMock(list, facts('/api/items', { headers: { 'X-Role': 'admin' } }))?.id).toBe('admin');
    expect(findMock(list, facts('/api/items?page=2', { headers: { 'x-role': 'admin' } }))?.id).toBe('page2');
  });
  it('a disabled mock with conditions is skipped', () => {
    expect(findMock(list, facts('/api/items?page=3'))?.id).toBe('all');
  });
  it('no catch-all and no condition met: no mock', () => {
    expect(findMock(list.slice(1), facts('/api/items?page=9'))).toBeNull();
  });
  it('the URL and method still have to match', () => {
    expect(findMock([mock('p', { method: 'POST', match: { query: { page: '2' } } })], facts('/api/items?page=2'))).toBeNull();
    expect(findMock([mock('p', { match: { query: { page: '2' } } })], facts('/api/other?page=2'))).toBeNull();
  });
});

describe('testCall passes headers', () => {
  it('a header condition can be tested', () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push(mock('all'), mock('admin', { match: { headers: { 'x-role': 'admin' } } }));
    const r = testCall(p, { method: 'GET', url: '/api/items', headers: { 'X-Role': 'admin' } }, 'http://a.test');
    expect(r.ok && r.mock?.id).toBe('admin');
    const r2 = testCall(p, { method: 'GET', url: '/api/items' }, 'http://a.test');
    expect(r2.ok && r2.mock?.id).toBe('all');
  });
});

describe('export and import carry match', () => {
  it('round-trips match', () => {
    const p = newProject('p', 'http://a.test');
    const m = mock('c', { match: { query: { a: '1' }, headers: { 'x-b': '*' }, body: '{"c":1}' } });
    p.scenarios[0]!.mocks.push(m);
    const r = parseProjectFile(exportProject(p));
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.match).toEqual(m.match);
  });
  it('rejects a match whose values are not strings', () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push(mock('c'));
    const file = JSON.parse(exportProject(p));
    const found = JSON.stringify(file).includes('"urlPattern"');
    expect(found).toBe(true);
    // Put a bad match on the first mock wherever the file keeps it.
    const text = exportProject(p).replace('"urlPattern"', '"match":{"query":{"a":1}},"urlPattern"');
    expect(parseProjectFile(text).ok).toBe(false);
  });
  it('a file without match still loads', () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push(mock('c'));
    const r = parseProjectFile(exportProject(p));
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.match).toBeUndefined();
  });
});

describe('a scenario still overrides Default (layers)', () => {
  it("Default's mock with conditions does not beat the active scenario's plain mock", () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push(mock('def-page2', { match: { query: { page: '2' } } }), mock('def-all'));
    p.scenarios.push({ id: 'down', name: 'Down', mocks: [mock('down-all')] });
    p.activeScenarioId = 'down';
    const r = testCall(p, { method: 'GET', url: '/api/items?page=2' }, 'http://a.test');
    expect(r.ok && r.mock?.id).toBe('down-all');
  });
  it("the scenario's own mock with conditions beats its plain one, and Default fills the gaps", () => {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push(mock('def-other', { urlPattern: '/api/other' }));
    p.scenarios.push({ id: 's', name: 'S', mocks: [mock('s-all'), mock('s-page2', { match: { query: { page: '2' } } })] });
    p.activeScenarioId = 's';
    const call = (url: string) => {
      const r = testCall(p, { method: 'GET', url }, 'http://a.test');
      return r.ok ? r.mock?.id : null;
    };
    expect(call('/api/items?page=2')).toBe('s-page2');
    expect(call('/api/items')).toBe('s-all');
    expect(call('/api/other')).toBe('def-other');
  });
});
